/// One event, as a destination receives it. The same shape for every type: read `type`, then `data`
public struct EventEnvelope: Codable, Equatable, Sendable {
    /// The event's own id. A redelivery of the same event carries the same one
    public var id: UUID
    /// What happened, such as `track.started`
    public var type: String
    /// When, as an ISO-8601 instant in UTC
    public var occurredAt: String
    public var station: EventStation
    /// What the type says it holds. `/events/types` gives an example of each
    public var data: [String: JSONValue]

    public init(id: UUID, type: String, occurredAt: String, station: EventStation, data: [String: JSONValue]) {
        self.id = id
        self.type = type
        self.occurredAt = occurredAt
        self.station = station
        self.data = data
    }

    private enum CodingKeys: String, CodingKey {
        case id = "id"
        case type = "type"
        case occurredAt = "occurredAt"
        case station = "station"
        case data = "data"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.id = try container.decode(UUID.self, forKey: .id)
        self.type = try container.decode(String.self, forKey: .type)
        self.occurredAt = try container.decode(String.self, forKey: .occurredAt)
        self.station = try container.decode(EventStation.self, forKey: .station)
        self.data = try container.decode([String: JSONValue].self, forKey: .data)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.id, forKey: .id)
        try container.encode(self.type, forKey: .type)
        try container.encode(self.occurredAt, forKey: .occurredAt)
        try container.encode(self.station, forKey: .station)
        try container.encode(self.data, forKey: .data)
    }
}

/// One kind of event the station sends
public struct EventType: Codable, Equatable, Sendable {
    public var type: String
    /// When it is sent, and what its `data` holds
    public var description: String
    /// False for the test event, which only a test delivery sends
    public var subscribable: Bool
    public var example: EventEnvelope

    public init(type: String, description: String, subscribable: Bool, example: EventEnvelope) {
        self.type = type
        self.description = description
        self.subscribable = subscribable
        self.example = example
    }

    private enum CodingKeys: String, CodingKey {
        case type = "type"
        case description = "description"
        case subscribable = "subscribable"
        case example = "example"
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.type = try container.decode(String.self, forKey: .type)
        self.description = try container.decode(String.self, forKey: .description)
        self.subscribable = try container.decode(Bool.self, forKey: .subscribable)
        self.example = try container.decode(EventEnvelope.self, forKey: .example)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.type, forKey: .type)
        try container.encode(self.description, forKey: .description)
        try container.encode(self.subscribable, forKey: .subscribable)
        try container.encode(self.example, forKey: .example)
    }
}

